class Component extends DCLogic {
renderVals() {
var self = this;
var rec = !!(this.state && this.state.rec);
return {
spin: rec ? 'gtekSpin 1.8s linear infinite' : 'none',
kicker: rec ? 'در حال ضبط…' : 'درس دوم · مکث',
label: rec ? 'پایان ضبط' : 'ضبط تمرین',
pressed: rec ? 'true' : 'false',
toggle: function () { self.setState({ rec: !rec }); }
};
}
}
return Component;
